#[test]fn policy_and_submitted_labels(){use mob_owners::MobOwners;assert_eq!(MobOwners::default().policy(true),1);assert_eq!(MobOwners{projectiles:true}.policy(true),3);assert_eq!(MobOwners{projectiles:true}.policy(false),0);use mob_owner_cache::*;begin(3);assert!(enabled(true));record(Label{owner:42,at:[1.0,2.0,3.0],height:2.0,light:0});assert_eq!(labels()[0].owner,42);assert!(labels().is_empty());remember(4,5);assert_eq!(remote_owner(4),Some(5));forget(4);assert_eq!(remote_owner(4),None);begin(0);assert!(!enabled(false));assert!(OWNABLE.contains(&"minecraft:vex"));assert!(OWNABLE.contains(&"minecraft:nautilus"));assert!(!OWNABLE.contains(&"minecraft:happy_ghast"));}
